-- =====================================================================
-- S.I. codes replaced from "SI Codes-All Included.xlsx", 22 Oct 2026.
--
-- 8563 rows -> 8516. The new list is a strict subset of what was there:
-- 47 codes removed, none added, no title changed. Among the 47 are the
-- six seven-digit codes and the 26 that the previous workbook and the
-- original seed disagreed about -- this file settles that by retiring
-- them.
--
-- One of the 47, 214410, was held by an employee. Their si_code is
-- cleared here, by the user's decision, so HR picks a replacement from
-- the new list.
--
-- Why this syncs the difference instead of emptying the table and
-- refilling it, which is what "replace" would suggest:
-- employees_si_code_fkey is checked per statement rather than at commit,
-- so DELETE FROM si_codes orphans codes the new list DOES contain --
-- 24730 among them -- before the INSERT can put them back, and the whole
-- transaction fails. Deleting only what is leaving never touches a code
-- that is both in use and staying. The end state is identical.
--
-- The table as it stood before is in si_codes_backup_20261022, which has
-- no grants and RLS on.
-- =====================================================================

begin;

update employees set si_code = null where si_code = '214410';

create temp table si_codes_incoming (code text primary key, title text not null) on commit drop;

