delete from si_codes l
 where not exists (select 1 from si_codes_incoming n where n.code = l.code);

insert into si_codes (code, title)
select n.code, n.title from si_codes_incoming n
on conflict (code) do update set title = excluded.title;

-- Refuse to commit on anything other than an exact match. A reference
-- table left half replaced is worse than one not replaced at all.
do $$
declare n_diff integer; n_dangling integer;
begin
  select count(*) into n_diff from (
    select code, title from si_codes
    except
    select code, title from si_codes_incoming
  ) q;
  select count(*) into n_dangling from employees e
   where e.si_code is not null
     and not exists (select 1 from si_codes s where s.code = e.si_code);
  if n_diff <> 0 then
    raise exception '% rows differ from the incoming list', n_diff;
  end if;
  if n_dangling <> 0 then
    raise exception '% employees point at a missing code', n_dangling;
  end if;
end $$;

commit;
